#!/bin/bash
# 小小酒館後端 v478：酒館居民頻道由機器人發開頭說明＋縭／蕪／桃三張陪陪介紹卡（每張上面有「# 名字」標題）。
# 以目前的 v467b 為底，只新增 resident-cards 並在 service-server 啟動它。
# 在主機的 root 終端機執行。任何一步失敗都會停止；重啟後健康檢查失敗會自動還原舊版。
set -euo pipefail
R="${TT_ROOT:-}"
TAG=20261101-v478
UNIT=$R/etc/systemd/system/tinytavern-service.service
say(){ printf '\n== %s\n' "$*"; }
CUR=$(grep -o 'tinytavern-service:[A-Za-z0-9._-]*' "$UNIT" | head -1 | cut -d: -f2)
SRC=$R/opt/tinytavern/releases/service-$CUR
DST=$R/opt/tinytavern/releases/service-$TAG
say "目前版本：$CUR"
[ -d "$SRC" ] || { echo "找不到目前版本的資料夾 $SRC，停止。"; exit 1; }
[ ! -e "$DST" ] || { echo "$DST 已經存在（可能已部署過），停止。"; exit 1; }
say "核對主機上的檔案與預期相同（v467b）"
cd "$SRC/order-voice-bot"
sha256sum -c --quiet - <<'SUMS' || { echo "主機上的檔案和預期不同（可能有人改過），為了安全停止，沒有任何變動。"; exit 1; }
8fe5f8b4eea06e6f5e70110b1a81884088c77c12637dd62d22907a31e62a3384  recruit-desk.cjs
29ba6dac508c9f587a2add8fbf336bcd8c33b24a5909ba4a2381cfcd0f718981  counter-desk.cjs
91e2dcfc2ace7b5901da36c8d671377c941cc78f5b7e271779d42c3b8c8d85bf  service-server.cjs
SUMS
cd /
say "建立新版本 $TAG"
cp -a "$SRC" "$DST"
base64 -d > "$DST/v478.tgz" <<'B64'
